// Asumiendo que 'items' contiene el array de respuesta de la API de Gemini
const geminiResponse = items[0].json;

// 1. Navega hasta la cadena de texto que contiene el JSON
const jsonStringWithCodeBlocks = geminiResponse.content.parts[0].text;

// 2. Limpia la cadena: elimina los bloques de código y los saltos de línea iniciales
const cleanedJsonString = jsonStringWithCodeBlocks
    .replace('```json\n', '') // Elimina el inicio del bloque de código
    .replace('```', '')     // Elimina el final del bloque de código
    .trim();                // Elimina cualquier espacio o salto de línea extra

// 3. Convierte la cadena limpia en un objeto JavaScript
const parsedJson = JSON.parse(cleanedJsonString);

// 4. Retorna el objeto JSON de la factura que te interesa
return [{ json: parsedJson.message.content.factura }];
